<?php
declare(strict_types=1);$config=require __DIR__.'/../config/config.php';require_once __DIR__.'/../app/Database.php';require_once __DIR__.'/../app/Auth.php';require_once __DIR__.'/../app/UserStorage.php';require_once __DIR__.'/../app/WorkspaceService.php';try{$u=(new Auth($config))->requireUser();$base=UserStorage::home($config,(int)$u['id']);$ws=new WorkspaceService(['workspace'=>$base]);$in=request_json();$path=(string)($in['path']??'');$content=(string)($in['content']??'');if($path===''||strlen($content)>2*1024*1024)throw new InvalidArgumentException('Caminho ou conteúdo inválido.');$safe=$ws->safe($path,false);if(!preg_match('/\.(txt|md|json|csv|html|css|js|php|py|cpp|h|hpp)$/i',$safe))throw new InvalidArgumentException('Extensão não permitida para edição.');$parent=dirname($safe);if(!is_dir($parent))mkdir($parent,0775,true);$stage=$base.DIRECTORY_SEPARATOR.'staging';if(!is_dir($stage))mkdir($stage,0775,true);$stageFile=$stage.DIRECTORY_SEPARATOR.bin2hex(random_bytes(8)).'.json';file_put_contents($stageFile,json_encode(['path'=>$path,'content'=>$content,'user_id'=>$u['id'],'created_at'=>date(DATE_ATOM)],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));if(($in['commit']??false)===true){if(file_put_contents($safe,$content,LOCK_EX)===false)throw new RuntimeException('Não foi possível salvar.');unlink($stageFile);json_response(['ok'=>true,'committed'=>true,'path'=>$path]);}json_response(['ok'=>true,'committed'=>false,'staging'=>$stageFile,'path'=>$path]);}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],400);}
